import{_ as l,o as t,c as i,a5 as e}from"./chunks/framework.bIR-4glx.js";const c=JSON.parse('{"title":"AI 评测记录模板","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/ai-evaluation.zh.md","filePath":"public/downloads/worksheets/ai-evaluation.zh.md","lastUpdated":1795488252000}'),r={name:"public/downloads/worksheets/ai-evaluation.zh.md"};function o(d,a,h,n,u,s){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="ai-评测记录模板" tabindex="-1">AI 评测记录模板 <a class="header-anchor" href="#ai-评测记录模板" aria-label="Permalink to &quot;AI 评测记录模板&quot;">​</a></h1><p>配合 <a href="https://byoungd.github.io/up/threads/practice/ai-evaluation" target="_blank" rel="noreferrer">AI 评测与可靠性</a> 使用。先填写标准，再运行案例。空表用于记录一个版本比较；示例数字不代表模型性能或通用上线门槛。</p><h2 id="可复制记录" tabindex="-1">可复制记录 <a class="header-anchor" href="#可复制记录" aria-label="Permalink to &quot;可复制记录&quot;">​</a></h2><h3 id="ai-evaluation-—-日期-任务" tabindex="-1">AI Evaluation — 日期 / 任务 <a class="header-anchor" href="#ai-evaluation-—-日期-任务" aria-label="Permalink to &quot;AI Evaluation — 日期 / 任务&quot;">​</a></h3><h4 id="范围" tabindex="-1">范围 <a class="header-anchor" href="#范围" aria-label="Permalink to &quot;范围&quot;">​</a></h4><ul><li>用户和要完成的动作：</li><li>输入材料、权限和去标识方式：</li><li>人工基线及总耗时：</li><li>不支持的任务：</li></ul><h4 id="测试设置-运行前固定" tabindex="-1">测试设置（运行前固定） <a class="header-anchor" href="#测试设置-运行前固定" aria-label="Permalink to &quot;测试设置（运行前固定）&quot;">​</a></h4><ul><li>当前版本 / 候选版本：</li><li>模型、提示、检索材料、工具版本：</li><li>运行日期、地区、记忆设置；无法固定的服务版本：</li><li>本轮只改变什么：</li><li>开发样本 / 未参与调优的保留样本：</li><li>每例运行次数及时间、调用、费用上限：</li><li>必须全部通过的条件：</li><li>可比较的质量与人工评分说明：</li><li>评分人 / 争议如何解决：</li><li>相关失败场景：来源缺失 / 提示注入 / 越权 / 失控重试或重复副作用 / 转写或识图错误：</li><li>长时任务字段：任务/运行编号、检查点、墙钟时间、超时、最大重试、重复安全标识、人工接管点：</li><li>隔离字段：干净环境、网络出口白名单、凭证范围、浏览器/页面不可信输入说明：</li><li>政策字段：供应商政策名称、版本、生效日期、地区、高风险人工复核：</li></ul><h4 id="逐例记录-每个版本分别复制本区" tabindex="-1">逐例记录（每个版本分别复制本区） <a class="header-anchor" href="#逐例记录-每个版本分别复制本区" aria-label="Permalink to &quot;逐例记录（每个版本分别复制本区）&quot;">​</a></h4><ul><li>本区版本：</li><li>ID 使用“案例编号 / 尝试序号”，例如 07 / 2；输入指向固定的案例材料。</li></ul><h5 id="案例-每次尝试复制一份" tabindex="-1">案例（每次尝试复制一份） <a class="header-anchor" href="#案例-每次尝试复制一份" aria-label="Permalink to &quot;案例（每次尝试复制一份）&quot;">​</a></h5><ul><li>案例编号 / 尝试序号：</li><li>类型与固定输入材料位置：</li><li>预期行为 / 判断依据：</li><li>支持结论的原文位置 / 音视频时间段 / 图片区域：</li><li>实际行为 / 产物位置：</li><li>过程记录 / 工具调用 / 授权记录位置：</li><li>检查点 / 恢复编号 / 重试与重复安全记录：</li><li>网络出口、页面或截图证据、凭证范围：</li><li>最终环境结果（文件、数据库或用户可见状态）：</li><li>首次是否合格 / 硬性条件失败：</li><li>人工修改分钟 / 修改内容：</li><li>最终状态（失败与超时也保留）：</li></ul><h4 id="汇总-每个版本单独计算-失败与超时保留在分母中" tabindex="-1">汇总（每个版本单独计算，失败与超时保留在分母中） <a class="header-anchor" href="#汇总-每个版本单独计算-失败与超时保留在分母中" aria-label="Permalink to &quot;汇总（每个版本单独计算，失败与超时保留在分母中）&quot;">​</a></h4><ul><li>首次合格数 / 全部尝试数：</li><li>必须条件失败及具体案例：</li><li>人工修改后合格数 / 全部尝试数：</li><li>准备、运行、核验、返工总分钟：</li><li>工具费用及工时估值口径：</li><li>本批总过程成本 / 最终合格数量：</li><li>证据限制与不支持的推断：</li></ul><h4 id="决定与后续" tabindex="-1">决定与后续 <a class="header-anchor" href="#决定与后续" aria-label="Permalink to &quot;决定与后续&quot;">​</a></h4><ul><li>采用 / 维持现状 / 修复复测 / 停止：</li><li>支持这个决定的案例：</li><li>新增回归案例及重跑范围：</li><li>模型、资料、工具或记忆变化后的复测触发；上次合格版本：</li><li>允许使用范围 / 人工接管 / 撤回触发：</li><li>换供应商、关闭记忆或断开工具后的退出演练结果：</li><li>负责人、复查日期、记录位置：</li></ul><p>若最终合格数量为零，每份合格结果成本写“无法计算”，保留已经发生的总支出，不用零替代。</p><h2 id="填写示例-公开资料比较表" tabindex="-1">填写示例：公开资料比较表 <a class="header-anchor" href="#填写示例-公开资料比较表" aria-label="Permalink to &quot;填写示例：公开资料比较表&quot;">​</a></h2><p>以下是假设案例，与章节示例一致：十条案例各运行一次，当前版本 A 首次合格 8 条，候选 B 首次合格 9 条；两版经人工修订后各合格 10 条。</p><table tabindex="0"><thead><tr><th>字段</th><th>示例填写</th></tr></thead><tbody><tr><td>本轮改变</td><td>只修改提取提示，材料与工具相同</td></tr><tr><td>必须条件</td><td>关键数字有出处；缺失价格不得推断</td></tr><tr><td>失败记录 B-07</td><td>原文未提供价格；B 写成“免费”；人工改回“未提供”</td></tr><tr><td>A 的成本</td><td>总工时 120 分钟，按 60 元/小时估值，工具 6 元；共 126 元</td></tr><tr><td>B 的成本</td><td>总工时 100 分钟，同样估值，工具 8 元；共 108 元</td></tr><tr><td>决定</td><td>保留当前范围；B 先修复，不扩大使用</td></tr><tr><td>下一步</td><td>加入缺价、价格过期、价格冲突案例，同时重跑此前合格案例</td></tr><tr><td>证据限制</td><td>小样本且每例一次；不能推断线上错误率；修订后正确不等于自主可靠</td></tr></tbody></table><p>把实际结果保存在可复查的文件中。记录“已完成”时，附上文件、测试输出或系统状态，而不只贴模型的完成声明。</p><h2 id="从记录到行动" tabindex="-1">从记录到行动 <a class="header-anchor" href="#从记录到行动" aria-label="Permalink to &quot;从记录到行动&quot;">​</a></h2><p>一轮只修复一个主要错误模式，并检查旧案例是否退步。流程仍不清楚时回到 <a href="https://byoungd.github.io/up/templates/ai-task-brief" target="_blank" rel="noreferrer">AI 任务简报</a>；项目准备对外服务时，再填写 <a href="https://byoungd.github.io/up/templates/startup-experiment" target="_blank" rel="noreferrer">创业实验卡</a>，分别验证结果质量与真实需求。</p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/ai-evaluation" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-10-16。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',25)])])}const p=l(r,[["render",o]]);export{c as __pageData,p as default};
